-- Supporting domains. External delivery/upload providers remain adapters outside this schema.
CREATE TABLE IF NOT EXISTS app.announcement (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), title text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')), published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.notification (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), user_id text REFERENCES auth."user"(id), channel text NOT NULL CHECK (channel IN ('in_app','email','sms','whatsapp','push')), subject text, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','failed','cancelled')), scheduled_at timestamptz, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.file_asset (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), storage_key text NOT NULL, original_filename text NOT NULL, content_type text NOT NULL, byte_size bigint NOT NULL CHECK (byte_size >= 0), checksum_sha256 char(64) NOT NULL, scan_status text NOT NULL DEFAULT 'pending' CHECK (scan_status IN ('pending','clean','infected','failed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, storage_key));
CREATE TABLE IF NOT EXISTS app.document_template (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), name text NOT NULL, template_type text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, name));
CREATE TABLE IF NOT EXISTS app.course (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), subject_id uuid REFERENCES app.subject(id), title text NOT NULL, description text, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.course_resource (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), course_id uuid NOT NULL REFERENCES app.course(id), file_asset_id uuid REFERENCES app.file_asset(id), title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.assignment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), course_id uuid NOT NULL REFERENCES app.course(id), class_id uuid NOT NULL REFERENCES app.class(id), title text NOT NULL, instructions text, due_at timestamptz, maximum_score numeric(7,2) CHECK (maximum_score IS NULL OR maximum_score > 0), status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','closed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.assignment_submission (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), assignment_id uuid NOT NULL REFERENCES app.assignment(id), student_id uuid NOT NULL REFERENCES app.student(id), file_asset_id uuid REFERENCES app.file_asset(id), submitted_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted','returned','late')), UNIQUE (tenant_id, assignment_id, student_id));
CREATE TABLE IF NOT EXISTS app.library_item (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), title text NOT NULL, author text, isbn text, item_type text NOT NULL DEFAULT 'book', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app.library_copy (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), item_id uuid NOT NULL REFERENCES app.library_item(id), barcode text NOT NULL, status text NOT NULL DEFAULT 'available' CHECK (status IN ('available','loaned','lost','archived')), UNIQUE (tenant_id, barcode));
CREATE TABLE IF NOT EXISTS app.library_loan (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), copy_id uuid NOT NULL REFERENCES app.library_copy(id), student_id uuid REFERENCES app.student(id), staff_id uuid REFERENCES app.staff(id), loaned_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz NOT NULL, returned_at timestamptz, CHECK (student_id IS NOT NULL OR staff_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS app.inventory_item (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), sku text NOT NULL, name text NOT NULL, quantity integer NOT NULL DEFAULT 0 CHECK (quantity >= 0), reorder_level integer NOT NULL DEFAULT 0 CHECK (reorder_level >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, sku));
CREATE TABLE IF NOT EXISTS app.canteen_menu (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), served_on date NOT NULL, label text NOT NULL, allergens text[] NOT NULL DEFAULT '{}', price_minor bigint NOT NULL DEFAULT 0 CHECK (price_minor >= 0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, served_on, label));
CREATE TABLE IF NOT EXISTS app.staff_absence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), staff_id uuid NOT NULL REFERENCES app.staff(id), starts_on date NOT NULL, ends_on date NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','approved','rejected','cancelled')), reason text, created_at timestamptz NOT NULL DEFAULT now(), CHECK (ends_on >= starts_on));
CREATE TABLE IF NOT EXISTS app.report_export (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES app.tenant(id), requested_by_user_id text REFERENCES auth."user"(id), report_type text NOT NULL, parameters jsonb NOT NULL DEFAULT '{}'::jsonb, file_asset_id uuid REFERENCES app.file_asset(id), status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','processing','completed','failed','expired')), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['announcement','notification','file_asset','document_template','course','course_resource','assignment','assignment_submission','library_item','library_copy','library_loan','inventory_item','canteen_menu','staff_absence','report_export'] LOOP
    EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON app.%I USING (tenant_id = app.current_tenant_id()) WITH CHECK (tenant_id = app.current_tenant_id())', t || '_tenant_isolation', t);
  END LOOP;
END $$;

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['document_template','course','assignment','inventory_item'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON app.%I', t || '_touch_updated_at', t);
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON app.%I FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at()', t || '_touch_updated_at', t);
  END LOOP;
END $$;
